import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import PracticeProgress from './components/PracticeProgress';
import SurvivalGame from './components/SurvivalGame';
import TimeAttackGame from './components/TimeAttackGame';
import CosmicDefenseGame from './components/CosmicDefenseGame';
import MiniGameMenu from './components/MiniGameMenu';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel, PracticeWord } from './types';
import { fetchQuotes, getPracticeLetter } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP, checkLevelProgress } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame, AlertTriangle, ArrowRight, Keyboard, ArrowUpCircle, Gamepad2, Brain, RefreshCcw } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  // PRACTICE MODE STATE
  const [practiceLevel, setPracticeLevel] = useState<number>(() => {
      const saved = localStorage.getItem('frogType_practiceLevel');
      return saved ? parseInt(saved, 10) : 0;
  });

  // Smart Practice Queue (Leitner-ish system)
  const [smartPracticeQueue, setSmartPracticeQueue] = useState<PracticeWord[]>(() => {
      const saved = localStorage.getItem('frogType_smartQueue');
      return saved ? JSON.parse(saved) : [];
  });

  // Failed Quotes Remediation Queue (New)
  // Maps quote text -> number of successful repetitions required (starts at 3)
  const [failedQuoteRepetitions, setFailedQuoteRepetitions] = useState<Record<string, number>>(() => {
      const saved = localStorage.getItem('frogType_remediations');
      return saved ? JSON.parse(saved) : {};
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  // New: Specific Character Statistics (e.g. {'a': 5, 'b': 2})
  const [charStats, setCharStats] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('frogType_charStats');
    return saved ? JSON.parse(saved) : {};
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};

    // Legacy migration helper values
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    // Construct settings with defaults
    const mergedSettings: Settings = {
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: false,
      mechanicalSoundPreset: 'THOCK',
      ambientVolume: 0.02, 
      musicConfig: { source: 'NONE', presetId: '' },
      themeId: 'CLASSIC',
      autoStartMusic: true, // Default to true
      ...parsed // Overwrite with saved values
    };

    // --- MIGRATION & LOGIC OVERRIDES ---

    // 1. Recover legacy brown noise setting if musicConfig wasn't explicitly saved
    if (legacyBrownNoiseEnabled && (!parsed.musicConfig || parsed.musicConfig.source === 'NONE')) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
        mergedSettings.ambientVolume = legacyVolume;
    }

    // 2. Auto-Start Logic
    if (mergedSettings.autoStartMusic) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'PIANO_SATIE' };
    } else {
        mergedSettings.musicConfig = { source: 'NONE', presetId: '' };
    }

    return mergedSettings;
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    // Default fallback
    return (saved as GameMode) || 'QUOTES';
  });

  // UI state for Mini Game Menu vs Actual Game
  const [isMiniGameMenuOpen, setIsMiniGameMenuOpen] = useState(false);
  const [activeMiniGame, setActiveMiniGame] = useState<string | null>(null);

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);
  const [shouldAutoFocus, setShouldAutoFocus] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);

  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  const frogletIndex = uniqueTiers.indexOf('Froglet');
  const isArcadeLocked = currentTierIndex < frogletIndex;

  // Practice Lock: Require 20 matches to gather data
  const isPracticeLocked = testHistory.length < 20;

  // Gating Check
  const avgWpmVal = getAverageWPM(wpmHistory);
  const remediationCount = Object.keys(failedQuoteRepetitions).length;
  const { isGated, reason } = checkLevelProgress(userXP, avgWpmVal, mistakePool.length, remediationCount);

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_smartQueue', JSON.stringify(smartPracticeQueue)); }, [smartPracticeQueue]);
  useEffect(() => { localStorage.setItem('frogType_charStats', JSON.stringify(charStats)); }, [charStats]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);
  useEffect(() => { localStorage.setItem('frogType_practiceLevel', practiceLevel.toString()); }, [practiceLevel]);
  useEffect(() => { localStorage.setItem('frogType_remediations', JSON.stringify(failedQuoteRepetitions)); }, [failedQuoteRepetitions]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'PRACTICE' && isPracticeLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'MINIGAMES' && isArcadeLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;
    if (gameMode === 'MINIGAMES') return; 

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);

      // 1. Fetch Standard Quotes
      const newQuotes = await fetchQuotes(5, completedQuotes, level.name, gameMode, practiceLevel, charStats, smartPracticeQueue);

      // 2. Inject Remediation Quotes (High Priority)
      // If we have failed quotes that need clearing, inject them.
      const pendingRemediations = Object.keys(failedQuoteRepetitions);

      if (pendingRemediations.length > 0 && gameMode === 'QUOTES') {
          // Shuffle remediations
          const toInject = pendingRemediations.sort(() => 0.5 - Math.random()).slice(0, 2);

          const injectionQuotes: Quote[] = toInject.map(text => ({
              text: text,
              source: "Remediation",
              author: `Repeat Required (${failedQuoteRepetitions[text]} left)`
          }));

          // Mix them in: 2 remediations + 3 new quotes
          const mixed = [...injectionQuotes, ...newQuotes.slice(0, 3)];
          // Shuffle again so it's not always first
          setQuotesQueue(prev => [...prev, ...mixed.sort(() => 0.5 - Math.random())]);
      } else {
          setQuotesQueue(prev => [...prev, ...newQuotes]);
      }

    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode, practiceLevel, charStats, smartPracticeQueue, failedQuoteRepetitions]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0 && gameMode !== 'MINIGAMES') {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3 && gameMode !== 'MINIGAMES') {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote || gameMode === 'MINIGAMES') return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode,
       practiceLevel
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    let finalXp = xpCalc; 
    setShouldAutoFocus(true);

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // --- REMEDIATION SUCCESS LOGIC ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        // Check if this quote was in the remediation list
        if (failedQuoteRepetitions[key] !== undefined) {
            setFailedQuoteRepetitions(prev => {
                const currentVal = prev[key];
                const newVal = currentVal - 1;
                const newObj = { ...prev };

                if (newVal <= 0) {
                    delete newObj[key];
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Redemption!",
                        description: "Failed quote mastered.",
                        icon: <RefreshCcw className="w-5 h-5 text-green-500" />,
                        type: 'INFO'
                    }]);
                } else {
                    newObj[key] = newVal;
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Progress Saved",
                        description: `${newVal} successful repetitions left.`,
                        icon: <RefreshCcw className="w-5 h-5 text-orange-500" />,
                        type: 'INFO'
                    }]);
                }
                return newObj;
            });
        }
    }

    // Fix Mistake Mode Logic
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; 
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // --- SMART PRACTICE LOGIC (MASTERY UPDATE) ---
    if (currentQuote) {
        const quoteWords = currentQuote.text.split(/\s+/).map(w => w.replace(/[^a-zA-Z]/g, '').toLowerCase()).filter(w => w.length > 1);

        const runMistakes = new Set(mistakes.map(w => w.toLowerCase()));

        setSmartPracticeQueue(prevQueue => {
            const newQueue = [...prevQueue];
            let changed = false;

            quoteWords.forEach(qWord => {
                const index = newQueue.findIndex(pw => pw.word === qWord);

                if (index !== -1) {
                    if (runMistakes.has(qWord)) {
                        newQueue[index] = { ...newQueue[index], proficiency: 0, lastPracticed: Date.now() };
                        changed = true;
                    } else {
                        const newProficiency = newQueue[index].proficiency + 1;
                        if (newProficiency >= 3) {
                            newQueue.splice(index, 1);
                        } else {
                            newQueue[index] = { ...newQueue[index], proficiency: newProficiency, lastPracticed: Date.now() };
                        }
                        changed = true;
                    }
                }
            });

            return changed ? newQueue : prevQueue;
        });
    }

    // Practice Mode Level Up Logic
    if (gameMode === 'PRACTICE') {
        if (retryCount === 0 && mistakes.length === 0 && wpm > 30) {
            const nextLevel = practiceLevel + 1;
            setPracticeLevel(nextLevel);
            const newLetter = getPracticeLetter(nextLevel);

            setNotificationQueue(prev => [...prev, {
                id: `practice_level_${nextLevel}`,
                title: "Practice Level Up!",
                description: `Unlocked letter: ${newLetter}`,
                icon: <ArrowUpCircle className="w-5 h-5 text-frog-green" />,
                type: 'INFO'
            }]);

            setQuotesQueue([]);
        }
    }

    if (currentQuote && gameMode !== 'FIX_MISTAKE' && gameMode !== 'PRACTICE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    handleXPGain(finalXp, avgWpm);

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleMiniGameOver = (score: number, xp: number, wave?: number) => {
      const gameName = activeMiniGame === 'SURVIVAL_SWAMP' ? 'Swamp Survival' 
        : activeMiniGame === 'SURVIVAL_ZOMBIE' ? 'Zombie Outbreak'
        : activeMiniGame === 'COSMIC_DEFENSE' ? 'Cosmic Defense'
        : 'Time Attack';

      const newTestResult: TestResult = {
          id: Date.now(),
          date: new Date().toISOString(),
          wpm: 0, 
          xpEarned: xp,
          mode: 'MINIGAMES',
          quoteText: `${gameName} - Score: ${score}${wave ? ` (Wave ${wave})` : ''}`,
          mistakes: [],
          retryCount: 0
      };
      setTestHistory(prev => [...prev, newTestResult]);

      handleXPGain(xp, getAverageWPM(wpmHistory));
      setNotificationQueue(prev => [...prev, {
          id: `survival_${Date.now()}`,
          title: "Arcade Run Complete",
          description: `Score: ${score} | +${xp} XP`,
          icon: <Skull className="w-5 h-5 text-red-500" />,
          type: 'INFO'
      }]);
  };

  const handleXPGain = (xpAmount: number, currentAvgWpm: number) => {
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + xpAmount;

    // Pass current remediation count to checkLevelProgress
    const currentRemediationCount = Object.keys(failedQuoteRepetitions).length;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = currentAvgWpm < nextLevelObj.requiredWpm;

         const isEggInternal = currentLevelObj.tier === 'Egg' && nextLevelObj.tier === 'Egg';
         const isTierJump = currentLevelObj.tier !== nextLevelObj.tier;
         const isRemediationGated = isTierJump && currentRemediationCount > 0;

         if (!isEggInternal && (isMasteryGated || isSpeedGated || isRemediationGated)) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#40D672', '#22c55e', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    if (gameMode !== 'MINIGAMES') {
        setStreak(prev => prev + 1);
    }

    // Update Daily Streak
    updateDailyStreakActivity();
  };

  const handleQuoteFail = () => {
    // --- REMEDIATION TRIGGER ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        setFailedQuoteRepetitions(prev => {
            // Strict: Failing resets debt to 3.
            return { ...prev, [key]: 3 }; 
        });

        setNotificationQueue(prev => [...prev, {
            id: `fail_${Date.now()}`,
            title: "Quote Failed",
            description: "You must now pass this quote 3 times to proceed.",
            icon: <AlertTriangle className="w-5 h-5 text-red-500" />,
            type: 'INFO'
        }]);
    }

    setStreak(0);
  };

  const handleMistake = (word?: string, expectedChar?: string, typedChar?: string) => {
    let penaltyMultiplier = 0.85; 

    if (gameMode === 'HARDCORE') {
        penaltyMultiplier = 0.5;
    } else if (gameMode === 'FIX_MISTAKE') {
        penaltyMultiplier = 0.95;
    }

    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    // Note: streak is reset in handleQuoteFail for consistency when the entire quote fails
    // But mistakes in 'QUOTES' mode cause instant failure via TypingArea logic which calls onFail.
    // However, onMistake is called *before* onFail in TypingArea.
    // So we reset streak here too just in case.
    setStreak(0);

    // Track Words for FIX MISTAKE mode (Classic)
    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });

       const cleanWord = word.toLowerCase().replace(/[^a-z]/g, '');
       if (cleanWord.length > 1) {
           setSmartPracticeQueue(prev => {
               const idx = prev.findIndex(p => p.word === cleanWord);
               if (idx !== -1) {
                   const updated = [...prev];
                   updated[idx] = { ...updated[idx], proficiency: 0, lastPracticed: Date.now() };
                   return updated;
               } else {
                   return [...prev, { word: cleanWord, proficiency: 0, lastPracticed: Date.now() }];
               }
           });
       }
    }

    // Track Specific Characters for Smart Practice
    if (expectedChar && /[a-zA-Z]/.test(expectedChar)) {
        const lowerChar = expectedChar.toLowerCase();
        setCharStats(prev => {
            const currentCount = prev[lowerChar] || 0;
            return { ...prev, [lowerChar]: currentCount + 1 };
        });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = useCallback((mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    if (mode === 'PRACTICE' && isPracticeLocked) return;
    if (mode === 'MINIGAMES' && isArcadeLocked) return;

    setShouldAutoFocus(false);

    if (mode === 'MINIGAMES') {
        setIsMiniGameMenuOpen(true);
        setActiveMiniGame(null);
    } else {
        setIsMiniGameMenuOpen(false);
        setActiveMiniGame(null);
        setGameMode(mode);
        setQuotesQueue([]); 
        setCurrentQuote(null); 
    }
  }, [mistakePool.length, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  const handleMiniGameSelect = (gameId: string) => {
      setGameMode('MINIGAMES');
      setActiveMiniGame(gameId);
      setIsMiniGameMenuOpen(false);
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-green', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  // Auto-redirect for Mastery Gate
  useEffect(() => {
      if (isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE') {
          const timer = setTimeout(() => {
              switchMode('FIX_MISTAKE');
              soundEngine.playKeypress(); // Audio cue
          }, 2000); // 2 second delay to see the orange screen
          return () => clearTimeout(timer);
      }
  }, [isGated, reason, gameMode, switchMode]);

  const renderMiniGame = () => {
      if (activeMiniGame === 'SURVIVAL_SWAMP') {
          return (
              <SurvivalGame 
                  variant="SWAMP"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'SURVIVAL_ZOMBIE') {
          return (
              <SurvivalGame 
                  variant="ZOMBIE"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'TIME_ATTACK') {
          return (
              <TimeAttackGame
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'COSMIC_DEFENSE') {
          return (
              <CosmicDefenseGame
                  onGameOver={handleMiniGameOver} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      // Fallback
      return (
          <div className="text-stone-400 p-10 text-center">
              Unknown Game Mode
              <button onClick={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} className="block mx-auto mt-4 text-frog-green underline">Return</button>
          </div>
      );
  };

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <div className="sticky top-0 z-40 flex flex-col shadow-sm transition-all">
          <header className="w-full bg-stone-50/95 backdrop-blur-md border-b border-stone-200 px-6 py-3">
            <div className="max-w-[1400px] mx-auto flex flex-col md:flex-row items-center justify-between gap-4">

              <div className="flex flex-col md:flex-row items-center gap-6 w-full md:w-auto">
                <div className="flex flex-col items-center md:items-start flex-shrink-0">
                  <h1 className="text-xl font-black text-frog-green tracking-tight flex items-center gap-2">
                    <span className="text-2xl">🐸</span> Frog Type
                  </h1>
                </div>

                <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50 overflow-x-auto max-w-full">
                  <button 
                      onClick={() => switchMode('QUOTES')}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${gameMode === 'QUOTES' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      <BookOpen className="w-3.5 h-3.5" /> Quotes
                  </button>
                  <button 
                      onClick={() => switchMode('PRACTICE')}
                      disabled={isPracticeLocked}
                      title={isPracticeLocked ? `Calibrating skill profile... (${testHistory.length}/20)` : "Smart Practice Mode"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame 
                            ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' 
                            : isPracticeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100 border border-stone-200' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isPracticeLocked ? <Lock className="w-3.5 h-3.5" /> : <Keyboard className="w-3.5 h-3.5" />} 
                      Practice
                  </button>
                  <button 
                      onClick={() => switchMode('HARDCORE')}
                      disabled={isHardcoreLocked}
                      title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'HARDCORE' && !isMiniGameMenuOpen && !activeMiniGame
                          ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                          : isHardcoreLocked 
                              ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                              : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                      Hardcore
                  </button>
                  <button 
                      onClick={() => switchMode('MINIGAMES')}
                      disabled={isArcadeLocked}
                      title={isArcadeLocked ? "Unlocks at Froglet level" : "Minigames & Boss Battles"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'MINIGAMES' || isMiniGameMenuOpen || activeMiniGame 
                            ? 'bg-purple-100 text-purple-600 shadow-sm ring-1 ring-purple-200' 
                            : isArcadeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isArcadeLocked ? <Lock className="w-3.5 h-3.5" /> : <Gamepad2 className="w-3.5 h-3.5" />} 
                      Arcade
                  </button>
                  <button 
                      onClick={() => switchMode('FIX_MISTAKE')}
                      disabled={mistakePool.length === 0}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'FIX_MISTAKE' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                        ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                        ${isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' ? 'ring-2 ring-red-500 bg-red-50 text-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.4)]' : ''}
                      `}
                      title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
                  >
                      <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
                  </button>
                </div>
              </div>

              <div className="flex items-center gap-1.5 shrink-0">
                   <button 
                     onClick={cycleReadAhead}
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                     title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
                   >
                      {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                      {raConfig.bonus && (
                          <span className="absolute -top-1 -right-1 bg-frog-green text-white text-[8px] px-1 rounded-full font-bold">
                              {raConfig.bonus.replace('+','')}
                          </span>
                      )}
                   </button>

                   <button 
                     onClick={toggleAchievements} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Achievements"
                   >
                      <Award className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleTheme} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Themes"
                   >
                      <Palette className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleStats} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Statistics & History"
                   >
                      <TrendingUp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleHelp} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="How to Play"
                   >
                      <CircleHelp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleMusic} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Background Music"
                   >
                      <Music className="w-5 h-5" />
                   </button>
                   <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2">
                      <SettingsIcon className="w-5 h-5" />
                   </button>
              </div>

            </div>
          </header>

          <div className="w-full bg-white/95 backdrop-blur-md border-b border-stone-200 px-6 py-2">
               <div className="max-w-[1400px] mx-auto">
                   <ProgressBar 
                     xp={userXP} 
                     avgWpm={getAverageWPM(wpmHistory)} 
                     mistakeCount={mistakePool.length} 
                     remediationCount={Object.keys(failedQuoteRepetitions).length}
                   />
               </div>
          </div>
      </div>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex flex-col items-center justify-center min-h-[60vh]">
          {isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' && (
              <div className="mb-8 relative group overflow-hidden bg-orange-400 text-white px-8 py-4 rounded-3xl shadow-xl shadow-orange-200 flex items-center gap-5 transition-all transform ring-4 ring-orange-100 animate-pulse z-50 cursor-wait">
                  <div className="absolute inset-0 bg-white/10 skew-x-12 -translate-x-full group-hover:translate-x-full transition-transform duration-1000 infinite"></div>
                  <div className="bg-white/20 p-3 rounded-full shadow-inner">
                      <AlertTriangle className="w-8 h-8 text-white fill-white/20" />
                  </div>
                  <div className="text-left">
                      <div className="font-black text-xl uppercase tracking-tight leading-none text-white">Evolution Pending</div>
                      <div className="font-medium text-sm text-orange-50 mt-1">
                          Redirecting to fix <span className="font-black text-white border-b-2 border-orange-200/50">{mistakePool.length} mistakes</span>...
                      </div>
                  </div>
                  <div className="bg-white text-orange-500 p-2.5 rounded-full shadow-lg ml-2 animate-spin">
                      <RefreshCcw className="w-6 h-6" />
                  </div>
              </div>
          )}

          {isGated && reason === 'REMEDIATION' && gameMode === 'QUOTES' && (
              <div className="mb-8 relative group overflow-hidden bg-orange-500 text-white px-8 py-4 rounded-3xl shadow-xl shadow-orange-200 flex items-center gap-5 transition-all transform hover:-translate-y-1 hover:shadow-2xl ring-4 ring-orange-100 animate-pulse z-50 cursor-default">
                  <div className="bg-white/20 p-3 rounded-full shadow-inner">
                      <RefreshCcw className="w-8 h-8 text-white fill-white/20" />
                  </div>
                  <div className="text-left">
                      <div className="font-black text-xl uppercase tracking-tight leading-none text-white">Tier Gated!</div>
                      <div className="font-medium text-sm text-orange-100 mt-1">
                          Remediate <span className="font-black text-white border-b-2 border-orange-300/50">{Object.keys(failedQuoteRepetitions).length} failed quotes</span>
                      </div>
                  </div>
              </div>
          )}

          {gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame && (
              <div className="w-full flex flex-col items-center">
                  {smartPracticeQueue.length > 0 && (
                      <div className="mb-4 flex items-center gap-2 text-stone-500 text-xs font-bold uppercase tracking-wide bg-stone-100 px-4 py-1.5 rounded-full">
                          <Brain className="w-4 h-4 text-purple-500" />
                          <span>Smart Queue: {smartPracticeQueue.length} words to master</span>
                      </div>
                  )}
                  <PracticeProgress level={practiceLevel} />
              </div>
          )}

          {isMiniGameMenuOpen ? (
              <MiniGameMenu 
                  onSelect={handleMiniGameSelect} 
                  onBack={() => setIsMiniGameMenuOpen(false)} 
              />
          ) : activeMiniGame ? (
              renderMiniGame()
          ) : (
             <>
                {loading && !currentQuote ? (
                    <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
                    <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                    <p className="font-mono text-xs">
                        Hatching wisdom...
                    </p>
                    </div>
                ) : currentQuote ? (
                    <TypingArea 
                    quote={currentQuote} 
                    onComplete={handleQuoteComplete} 
                    onFail={handleQuoteFail}
                    onMistake={handleMistake}
                    onRequestNewQuote={handleRequestNextQuote}
                    streak={streak}
                    ghostWpm={getAverageWPM(wpmHistory)}
                    settings={settings}
                    gameMode={gameMode}
                    onInteract={() => setIsMusicOpen(false)}
                    autoFocus={shouldAutoFocus}
                    />
                ) : (
                    <div className="flex flex-col items-center justify-center text-stone-400">
                    <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                    <p className="font-mono text-xs">Fetching wisdom...</p>
                    </div>
                )}
             </>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} 
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import PracticeProgress from './components/PracticeProgress';
import SurvivalGame from './components/SurvivalGame';
import TimeAttackGame from './components/TimeAttackGame';
import CosmicDefenseGame from './components/CosmicDefenseGame';
import MiniGameMenu from './components/MiniGameMenu';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel, PracticeWord } from './types';
import { fetchQuotes, getPracticeLetter } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP, checkLevelProgress } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame, AlertTriangle, ArrowRight, Keyboard, ArrowUpCircle, Gamepad2, Brain, RefreshCcw } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  // PRACTICE MODE STATE
  const [practiceLevel, setPracticeLevel] = useState<number>(() => {
      const saved = localStorage.getItem('frogType_practiceLevel');
      return saved ? parseInt(saved, 10) : 0;
  });

  // Smart Practice Queue (Leitner-ish system)
  const [smartPracticeQueue, setSmartPracticeQueue] = useState<PracticeWord[]>(() => {
      const saved = localStorage.getItem('frogType_smartQueue');
      return saved ? JSON.parse(saved) : [];
  });

  // Failed Quotes Remediation Queue (New)
  // Maps quote text -> number of successful repetitions required (starts at 3)
  const [failedQuoteRepetitions, setFailedQuoteRepetitions] = useState<Record<string, number>>(() => {
      const saved = localStorage.getItem('frogType_remediations');
      return saved ? JSON.parse(saved) : {};
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  // New: Specific Character Statistics (e.g. {'a': 5, 'b': 2})
  const [charStats, setCharStats] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('frogType_charStats');
    return saved ? JSON.parse(saved) : {};
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};

    // Legacy migration helper values
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    // Construct settings with defaults
    const mergedSettings: Settings = {
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: false,
      mechanicalSoundPreset: 'THOCK',
      ambientVolume: 0.02, 
      musicConfig: { source: 'NONE', presetId: '' },
      themeId: 'CLASSIC',
      autoStartMusic: true, // Default to true
      ...parsed // Overwrite with saved values
    };

    // --- MIGRATION & LOGIC OVERRIDES ---

    // 1. Recover legacy brown noise setting if musicConfig wasn't explicitly saved
    if (legacyBrownNoiseEnabled && (!parsed.musicConfig || parsed.musicConfig.source === 'NONE')) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
        mergedSettings.ambientVolume = legacyVolume;
    }

    // 2. Auto-Start Logic
    if (mergedSettings.autoStartMusic) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'PIANO_SATIE' };
    } else {
        mergedSettings.musicConfig = { source: 'NONE', presetId: '' };
    }

    return mergedSettings;
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    // Default fallback
    return (saved as GameMode) || 'QUOTES';
  });

  // UI state for Mini Game Menu vs Actual Game
  const [isMiniGameMenuOpen, setIsMiniGameMenuOpen] = useState(false);
  const [activeMiniGame, setActiveMiniGame] = useState<string | null>(null);

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);
  const [shouldAutoFocus, setShouldAutoFocus] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);

  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  const frogletIndex = uniqueTiers.indexOf('Froglet');
  const isArcadeLocked = currentTierIndex < frogletIndex;

  // Practice Lock: Require 20 matches to gather data
  const isPracticeLocked = testHistory.length < 20;

  // Gating Check
  const avgWpmVal = getAverageWPM(wpmHistory);
  const remediationCount = Object.keys(failedQuoteRepetitions).length;
  const { isGated, reason } = checkLevelProgress(userXP, avgWpmVal, mistakePool.length, remediationCount);

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_smartQueue', JSON.stringify(smartPracticeQueue)); }, [smartPracticeQueue]);
  useEffect(() => { localStorage.setItem('frogType_charStats', JSON.stringify(charStats)); }, [charStats]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);
  useEffect(() => { localStorage.setItem('frogType_practiceLevel', practiceLevel.toString()); }, [practiceLevel]);
  useEffect(() => { localStorage.setItem('frogType_remediations', JSON.stringify(failedQuoteRepetitions)); }, [failedQuoteRepetitions]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'PRACTICE' && isPracticeLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'MINIGAMES' && isArcadeLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    // Allow random selection including duplicates to reinforce learning
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;
    if (gameMode === 'MINIGAMES') return; 

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);

      // 1. Fetch Standard Quotes
      const newQuotes = await fetchQuotes(5, completedQuotes, level.name, gameMode, practiceLevel, charStats, smartPracticeQueue);

      // 2. Inject Remediation Quotes (High Priority)
      // If we have failed quotes that need clearing, inject them.
      const pendingRemediations = Object.keys(failedQuoteRepetitions);

      if (pendingRemediations.length > 0 && gameMode === 'QUOTES') {
          // Shuffle remediations
          const toInject = pendingRemediations.sort(() => 0.5 - Math.random()).slice(0, 2);

          const injectionQuotes: Quote[] = toInject.map(text => ({
              text: text,
              source: "Remediation",
              author: `Repeat Required (${failedQuoteRepetitions[text]} left)`
          }));

          // Mix them in: 2 remediations + 3 new quotes
          const mixed = [...injectionQuotes, ...newQuotes.slice(0, 3)];
          // Shuffle again so it's not always first
          setQuotesQueue(prev => [...prev, ...mixed.sort(() => 0.5 - Math.random())]);
      } else {
          setQuotesQueue(prev => [...prev, ...newQuotes]);
      }

    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode, practiceLevel, charStats, smartPracticeQueue, failedQuoteRepetitions]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0 && gameMode !== 'MINIGAMES') {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3 && gameMode !== 'MINIGAMES') {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote || gameMode === 'MINIGAMES') return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode,
       practiceLevel
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    let finalXp = xpCalc; 
    setShouldAutoFocus(true);

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // --- REMEDIATION SUCCESS LOGIC ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        // Check if this quote was in the remediation list
        if (failedQuoteRepetitions[key] !== undefined) {
            setFailedQuoteRepetitions(prev => {
                const currentVal = prev[key];
                const newVal = currentVal - 1;
                const newObj = { ...prev };

                if (newVal <= 0) {
                    delete newObj[key];
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Redemption!",
                        description: "Failed quote mastered.",
                        icon: <RefreshCcw className="w-5 h-5 text-green-500" />,
                        type: 'INFO'
                    }]);
                } else {
                    newObj[key] = newVal;
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Progress Saved",
                        description: `${newVal} successful repetitions left.`,
                        icon: <RefreshCcw className="w-5 h-5 text-orange-500" />,
                        type: 'INFO'
                    }]);
                }
                return newObj;
            });
        }
    }

    // Fix Mistake Mode Logic - Updated to remove only one instance per successful type
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = currentQuote.text.split(' '); // Keep all instances
      setMistakePool(prev => {
          const newPool = [...prev];
          wordsFixed.forEach(fixedWord => {
              const idx = newPool.indexOf(fixedWord);
              if (idx > -1) newPool.splice(idx, 1);
          });
          return newPool;
      });
    }

    // --- SMART PRACTICE LOGIC (MASTERY UPDATE) ---
    if (currentQuote) {
        const quoteWords = currentQuote.text.split(/\s+/).map(w => w.replace(/[^a-zA-Z]/g, '').toLowerCase()).filter(w => w.length > 1);

        const runMistakes = new Set(mistakes.map(w => w.toLowerCase()));

        setSmartPracticeQueue(prevQueue => {
            const newQueue = [...prevQueue];
            let changed = false;

            quoteWords.forEach(qWord => {
                const index = newQueue.findIndex(pw => pw.word === qWord);

                if (index !== -1) {
                    if (runMistakes.has(qWord)) {
                        newQueue[index] = { ...newQueue[index], proficiency: 0, lastPracticed: Date.now() };
                        changed = true;
                    } else {
                        const newProficiency = newQueue[index].proficiency + 1;
                        if (newProficiency >= 3) {
                            newQueue.splice(index, 1);
                        } else {
                            newQueue[index] = { ...newQueue[index], proficiency: newProficiency, lastPracticed: Date.now() };
                        }
                        changed = true;
                    }
                }
            });

            return changed ? newQueue : prevQueue;
        });
    }

    // Practice Mode Level Up Logic
    if (gameMode === 'PRACTICE') {
        if (retryCount === 0 && mistakes.length === 0 && wpm > 30) {
            const nextLevel = practiceLevel + 1;
            setPracticeLevel(nextLevel);
            const newLetter = getPracticeLetter(nextLevel);

            setNotificationQueue(prev => [...prev, {
                id: `practice_level_${nextLevel}`,
                title: "Practice Level Up!",
                description: `Unlocked letter: ${newLetter}`,
                icon: <ArrowUpCircle className="w-5 h-5 text-frog-green" />,
                type: 'INFO'
            }]);

            setQuotesQueue([]);
        }
    }

    if (currentQuote && gameMode !== 'FIX_MISTAKE' && gameMode !== 'PRACTICE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    handleXPGain(finalXp, avgWpm);

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleMiniGameOver = (score: number, xp: number, wave?: number) => {
      const gameName = activeMiniGame === 'SURVIVAL_SWAMP' ? 'Swamp Survival' 
        : activeMiniGame === 'SURVIVAL_ZOMBIE' ? 'Zombie Outbreak'
        : activeMiniGame === 'COSMIC_DEFENSE' ? 'Cosmic Defense'
        : 'Time Attack';

      const newTestResult: TestResult = {
          id: Date.now(),
          date: new Date().toISOString(),
          wpm: 0, 
          xpEarned: xp,
          mode: 'MINIGAMES',
          quoteText: `${gameName} - Score: ${score}${wave ? ` (Wave ${wave})` : ''}`,
          mistakes: [],
          retryCount: 0
      };
      setTestHistory(prev => [...prev, newTestResult]);

      handleXPGain(xp, getAverageWPM(wpmHistory));
      setNotificationQueue(prev => [...prev, {
          id: `survival_${Date.now()}`,
          title: "Arcade Run Complete",
          description: `Score: ${score} | +${xp} XP`,
          icon: <Skull className="w-5 h-5 text-red-500" />,
          type: 'INFO'
      }]);
  };

  const handleXPGain = (xpAmount: number, currentAvgWpm: number) => {
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + xpAmount;

    // Pass current remediation count to checkLevelProgress
    const currentRemediationCount = Object.keys(failedQuoteRepetitions).length;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = currentAvgWpm < nextLevelObj.requiredWpm;

         const isEggInternal = currentLevelObj.tier === 'Egg' && nextLevelObj.tier === 'Egg';
         const isTierJump = currentLevelObj.tier !== nextLevelObj.tier;
         const isRemediationGated = isTierJump && currentRemediationCount > 0;

         if (!isEggInternal && (isMasteryGated || isSpeedGated || isRemediationGated)) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#40D672', '#22c55e', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    if (gameMode !== 'MINIGAMES') {
        setStreak(prev => prev + 1);
    }

    // Update Daily Streak
    updateDailyStreakActivity();
  };

  const handleQuoteFail = () => {
    // --- REMEDIATION TRIGGER ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        setFailedQuoteRepetitions(prev => {
            // Strict: Failing resets debt to 3.
            return { ...prev, [key]: 3 }; 
        });

        setNotificationQueue(prev => [...prev, {
            id: `fail_${Date.now()}`,
            title: "Quote Failed",
            description: "You must now pass this quote 3 times to proceed.",
            icon: <AlertTriangle className="w-5 h-5 text-red-500" />,
            type: 'INFO'
        }]);
    }

    setStreak(0);
  };

  const handleMistake = (word?: string, expectedChar?: string, typedChar?: string) => {
    let penaltyMultiplier = 0.85; 

    if (gameMode === 'HARDCORE') {
        penaltyMultiplier = 0.5;
    } else if (gameMode === 'FIX_MISTAKE') {
        penaltyMultiplier = 0.95;
    }

    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    // Note: streak is reset in handleQuoteFail for consistency when the entire quote fails
    // But mistakes in 'QUOTES' mode cause instant failure via TypingArea logic which calls onFail.
    // However, onMistake is called *before* onFail in TypingArea.
    // So we reset streak here too just in case.
    setStreak(0);

    // Track Words for FIX MISTAKE mode (Classic) - REQUIRE 3 REPETITIONS TO CLEAR
    if (word && word.length > 1) {
       setMistakePool(prev => {
         // Reset this word's debt to 3 if mistakenly typed
         const clean = prev.filter(w => w !== word);
         return [...clean, word, word, word];
       });

       const cleanWord = word.toLowerCase().replace(/[^a-z]/g, '');
       if (cleanWord.length > 1) {
           setSmartPracticeQueue(prev => {
               const idx = prev.findIndex(p => p.word === cleanWord);
               if (idx !== -1) {
                   const updated = [...prev];
                   updated[idx] = { ...updated[idx], proficiency: 0, lastPracticed: Date.now() };
                   return updated;
               } else {
                   return [...prev, { word: cleanWord, proficiency: 0, lastPracticed: Date.now() }];
               }
           });
       }
    }

    // Track Specific Characters for Smart Practice
    if (expectedChar && /[a-zA-Z]/.test(expectedChar)) {
        const lowerChar = expectedChar.toLowerCase();
        setCharStats(prev => {
            const currentCount = prev[lowerChar] || 0;
            return { ...prev, [lowerChar]: currentCount + 1 };
        });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = useCallback((mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    if (mode === 'PRACTICE' && isPracticeLocked) return;
    if (mode === 'MINIGAMES' && isArcadeLocked) return;

    setShouldAutoFocus(false);

    if (mode === 'MINIGAMES') {
        setIsMiniGameMenuOpen(true);
        setActiveMiniGame(null);
    } else {
        setIsMiniGameMenuOpen(false);
        setActiveMiniGame(null);
        setGameMode(mode);
        setQuotesQueue([]); 
        setCurrentQuote(null); 
    }
  }, [mistakePool.length, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  const handleMiniGameSelect = (gameId: string) => {
      setGameMode('MINIGAMES');
      setActiveMiniGame(gameId);
      setIsMiniGameMenuOpen(false);
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-green', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  // Auto-redirect for Mastery Gate
  useEffect(() => {
      if (isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE') {
          const timer = setTimeout(() => {
              switchMode('FIX_MISTAKE');
              soundEngine.playKeypress(); // Audio cue
          }, 2000); // 2 second delay to see the orange screen
          return () => clearTimeout(timer);
      }
  }, [isGated, reason, gameMode, switchMode]);

  const renderMiniGame = () => {
      if (activeMiniGame === 'SURVIVAL_SWAMP') {
          return (
              <SurvivalGame 
                  variant="SWAMP"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'SURVIVAL_ZOMBIE') {
          return (
              <SurvivalGame 
                  variant="ZOMBIE"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'TIME_ATTACK') {
          return (
              <TimeAttackGame
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'COSMIC_DEFENSE') {
          return (
              <CosmicDefenseGame
                  onGameOver={handleMiniGameOver} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      // Fallback
      return (
          <div className="text-stone-400 p-10 text-center">
              Unknown Game Mode
              <button onClick={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} className="block mx-auto mt-4 text-frog-green underline">Return</button>
          </div>
      );
  };

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <div className="sticky top-0 z-40 flex flex-col shadow-sm transition-all">
          <header className="w-full bg-stone-50/95 backdrop-blur-md border-b border-stone-200 px-6 py-3">
            <div className="max-w-[1400px] mx-auto flex flex-col md:flex-row items-center justify-between gap-4">

              <div className="flex flex-col md:flex-row items-center gap-6 w-full md:w-auto">
                <div className="flex flex-col items-center md:items-start flex-shrink-0">
                  <h1 className="text-xl font-black text-frog-green tracking-tight flex items-center gap-2">
                    <span className="text-2xl">🐸</span> Frog Type
                  </h1>
                </div>

                <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50 overflow-x-auto max-w-full">
                  <button 
                      onClick={() => switchMode('QUOTES')}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${gameMode === 'QUOTES' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      <BookOpen className="w-3.5 h-3.5" /> Quotes
                  </button>
                  <button 
                      onClick={() => switchMode('PRACTICE')}
                      disabled={isPracticeLocked}
                      title={isPracticeLocked ? `Calibrating skill profile... (${testHistory.length}/20)` : "Smart Practice Mode"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame 
                            ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' 
                            : isPracticeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100 border border-stone-200' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isPracticeLocked ? <Lock className="w-3.5 h-3.5" /> : <Keyboard className="w-3.5 h-3.5" />} 
                      Practice
                  </button>
                  <button 
                      onClick={() => switchMode('HARDCORE')}
                      disabled={isHardcoreLocked}
                      title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'HARDCORE' && !isMiniGameMenuOpen && !activeMiniGame
                          ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                          : isHardcoreLocked 
                              ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                              : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                      Hardcore
                  </button>
                  <button 
                      onClick={() => switchMode('MINIGAMES')}
                      disabled={isArcadeLocked}
                      title={isArcadeLocked ? "Unlocks at Froglet level" : "Minigames & Boss Battles"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'MINIGAMES' || isMiniGameMenuOpen || activeMiniGame 
                            ? 'bg-purple-100 text-purple-600 shadow-sm ring-1 ring-purple-200' 
                            : isArcadeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isArcadeLocked ? <Lock className="w-3.5 h-3.5" /> : <Gamepad2 className="w-3.5 h-3.5" />} 
                      Arcade
                  </button>
                  <button 
                      onClick={() => switchMode('FIX_MISTAKE')}
                      disabled={mistakePool.length === 0}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'FIX_MISTAKE' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                        ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                        ${isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' ? 'ring-2 ring-orange-200 bg-orange-200 text-orange-900 animate-pulse shadow-[0_0_10px_rgba(253,186,116,0.6)]' : ''}
                      `}
                      title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
                  >
                      <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
                  </button>
                </div>
              </div>

              <div className="flex items-center gap-1.5 shrink-0">
                   <button 
                     onClick={cycleReadAhead}
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                     title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
                   >
                      {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                      {raConfig.bonus && (
                          <span className="absolute -top-1 -right-1 bg-frog-green text-white text-[8px] px-1 rounded-full font-bold">
                              {raConfig.bonus.replace('+','')}
                          </span>
                      )}
                   </button>

                   <button 
                     onClick={toggleAchievements} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Achievements"
                   >
                      <Award className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleTheme} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Themes"
                   >
                      <Palette className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleStats} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Statistics & History"
                   >
                      <TrendingUp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleHelp} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="How to Play"
                   >
                      <CircleHelp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleMusic} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Background Music"
                   >
                      <Music className="w-5 h-5" />
                   </button>
                   <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2">
                      <SettingsIcon className="w-5 h-5" />
                   </button>
              </div>

            </div>
          </header>

          <div className="w-full bg-white/95 backdrop-blur-md border-b border-stone-200 px-6 py-2">
               <div className="max-w-[1400px] mx-auto">
                   <ProgressBar 
                     xp={userXP} 
                     avgWpm={getAverageWPM(wpmHistory)} 
                     mistakeCount={mistakePool.length} 
                     remediationCount={Object.keys(failedQuoteRepetitions).length}
                   />
               </div>
          </div>
      </div>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex flex-col items-center justify-center min-h-[60vh]">
          {isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' && (
              <div className="mb-8 relative group overflow-hidden bg-orange-200 text-orange-900 px-8 py-4 rounded-3xl shadow-xl shadow-orange-100 flex items-center gap-5 transition-all transform ring-4 ring-orange-100 animate-pulse z-50 cursor-wait">
                  <div className="absolute inset-0 bg-white/30 skew-x-12 -translate-x-full group-hover:translate-x-full transition-transform duration-1000 infinite"></div>
                  <div className="bg-white/50 p-3 rounded-full shadow-inner text-orange-600">
                      <AlertTriangle className="w-8 h-8" />
                  </div>
                  <div className="text-left">
                      <div className="font-black text-xl uppercase tracking-tight leading-none text-orange-800">Evolution Pending</div>
                      <div className="font-medium text-sm text-orange-700 mt-1">
                          Redirecting to fix <span className="font-black border-b-2 border-orange-400">{mistakePool.length} pending corrections</span>...
                      </div>
                  </div>
                  <div className="bg-white text-orange-500 p-2.5 rounded-full shadow-lg ml-2 animate-spin">
                      <RefreshCcw className="w-6 h-6" />
                  </div>
              </div>
          )}

          {isGated && reason === 'REMEDIATION' && gameMode === 'QUOTES' && (
              <div className="mb-8 relative group overflow-hidden bg-orange-500 text-white px-8 py-4 rounded-3xl shadow-xl shadow-orange-200 flex items-center gap-5 transition-all transform hover:-translate-y-1 hover:shadow-2xl ring-4 ring-orange-100 animate-pulse z-50 cursor-default">
                  <div className="bg-white/20 p-3 rounded-full shadow-inner">
                      <RefreshCcw className="w-8 h-8 text-white fill-white/20" />
                  </div>
                  <div className="text-left">
                      <div className="font-black text-xl uppercase tracking-tight leading-none text-white">Tier Gated!</div>
                      <div className="font-medium text-sm text-orange-100 mt-1">
                          Remediate <span className="font-black text-white border-b-2 border-orange-300/50">{Object.keys(failedQuoteRepetitions).length} failed quotes</span>
                      </div>
                  </div>
              </div>
          )}

          {gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame && (
              <div className="w-full flex flex-col items-center">
                  {smartPracticeQueue.length > 0 && (
                      <div className="mb-4 flex items-center gap-2 text-stone-500 text-xs font-bold uppercase tracking-wide bg-stone-100 px-4 py-1.5 rounded-full">
                          <Brain className="w-4 h-4 text-purple-500" />
                          <span>Smart Queue: {smartPracticeQueue.length} words to master</span>
                      </div>
                  )}
                  <PracticeProgress level={practiceLevel} />
              </div>
          )}

          {isMiniGameMenuOpen ? (
              <MiniGameMenu 
                  onSelect={handleMiniGameSelect} 
                  onBack={() => setIsMiniGameMenuOpen(false)} 
              />
          ) : activeMiniGame ? (
              renderMiniGame()
          ) : (
             <>
                {loading && !currentQuote ? (
                    <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
                    <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                    <p className="font-mono text-xs">
                        Hatching wisdom...
                    </p>
                    </div>
                ) : currentQuote ? (
                    <TypingArea 
                    quote={currentQuote} 
                    onComplete={handleQuoteComplete} 
                    onFail={handleQuoteFail}
                    onMistake={handleMistake}
                    onRequestNewQuote={handleRequestNextQuote}
                    streak={streak}
                    ghostWpm={getAverageWPM(wpmHistory)}
                    settings={settings}
                    gameMode={gameMode}
                    onInteract={() => setIsMusicOpen(false)}
                    autoFocus={shouldAutoFocus}
                    />
                ) : (
                    <div className="flex flex-col items-center justify-center text-stone-400">
                    <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                    <p className="font-mono text-xs">Fetching wisdom...</p>
                    </div>
                )}
             </>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} 
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useLayoutEffect, useRef } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import PracticeProgress from './components/PracticeProgress';
import SurvivalGame from './components/SurvivalGame';
import TimeAttackGame from './components/TimeAttackGame';
import CosmicDefenseGame from './components/CosmicDefenseGame';
import MiniGameMenu from './components/MiniGameMenu';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult, NotificationItem, ReadAheadLevel, PracticeWord } from './types';
import { fetchQuotes, getPracticeLetter } from './services/quoteService';
import { getCurrentLevel, getNextLevel, getAverageWPM, LEVELS, calculateXP, checkLevelProgress } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award, Radio, Lock, Eye, EyeOff, Flame, AlertTriangle, ArrowRight, Keyboard, ArrowUpCircle, Gamepad2, Brain, RefreshCcw } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';
import { RADIO_STATIONS } from './data/radioStations';

const App: React.FC = () => {
  // User Stats Persistence
  const [userName, setUserName] = useState<string>(() => {
      return localStorage.getItem('frogType_userName') || 'Froggy';
  });

  const [joinDate, setJoinDate] = useState<string>(() => {
      const stored = localStorage.getItem('frogType_joinDate');
      if (stored) return stored;
      const now = new Date().toISOString();
      localStorage.setItem('frogType_joinDate', now);
      return now;
  });

  const [totalTimePlayed, setTotalTimePlayed] = useState<number>(() => {
      const stored = localStorage.getItem('frogType_totalTime');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const currentLevel = getCurrentLevel(userXP);

  // Track unlocked tiers persistently to prevent repeat notifications
  const [unlockedTiers, setUnlockedTiers] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_unlockedTiers');
    return saved ? JSON.parse(saved) : [];
  });

  // Session Streak (Consecutive Quotes)
  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  // Daily Streak Logic
  const [dailyStreak, setDailyStreak] = useState<number>(() => {
     const saved = localStorage.getItem('frogType_dailyStreak');
     return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  // PRACTICE MODE STATE
  const [practiceLevel, setPracticeLevel] = useState<number>(() => {
      const saved = localStorage.getItem('frogType_practiceLevel');
      return saved ? parseInt(saved, 10) : 0;
  });

  // Smart Practice Queue (Leitner-ish system)
  const [smartPracticeQueue, setSmartPracticeQueue] = useState<PracticeWord[]>(() => {
      const saved = localStorage.getItem('frogType_smartQueue');
      return saved ? JSON.parse(saved) : [];
  });

  // Failed Quotes Remediation Queue (New)
  // Maps quote text -> number of successful repetitions required (starts at 3)
  const [failedQuoteRepetitions, setFailedQuoteRepetitions] = useState<Record<string, number>>(() => {
      const saved = localStorage.getItem('frogType_remediations');
      return saved ? JSON.parse(saved) : {};
  });

  const [notificationQueue, setNotificationQueue] = useState<NotificationItem[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  // New: Specific Character Statistics (e.g. {'a': 5, 'b': 2})
  const [charStats, setCharStats] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('frogType_charStats');
    return saved ? JSON.parse(saved) : {};
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};

    // Legacy migration helper values
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    let initialReadAhead = parsed.readAheadLevel;
    if (parsed.readAheadEnabled === true && !initialReadAhead) initialReadAhead = 'FOCUS';
    if (!initialReadAhead) initialReadAhead = 'NONE';

    // Construct settings with defaults
    const mergedSettings: Settings = {
      ghostEnabled: false, 
      readAheadLevel: initialReadAhead, 
      sfxEnabled: true,
      mechanicalSoundEnabled: false,
      mechanicalSoundPreset: 'THOCK',
      ambientVolume: 0.02, 
      musicConfig: { source: 'NONE', presetId: '' },
      themeId: 'CLASSIC',
      autoStartMusic: true, // Default to true
      ...parsed // Overwrite with saved values
    };

    // --- MIGRATION & LOGIC OVERRIDES ---

    // 1. Recover legacy brown noise setting if musicConfig wasn't explicitly saved
    if (legacyBrownNoiseEnabled && (!parsed.musicConfig || parsed.musicConfig.source === 'NONE')) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
        mergedSettings.ambientVolume = legacyVolume;
    }

    // 2. Auto-Start Logic
    if (mergedSettings.autoStartMusic) {
        mergedSettings.musicConfig = { source: 'GENERATED', presetId: 'PIANO_SATIE' };
    } else {
        mergedSettings.musicConfig = { source: 'NONE', presetId: '' };
    }

    return mergedSettings;
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    // Default fallback
    return (saved as GameMode) || 'QUOTES';
  });

  // UI state for Mini Game Menu vs Actual Game
  const [isMiniGameMenuOpen, setIsMiniGameMenuOpen] = useState(false);
  const [activeMiniGame, setActiveMiniGame] = useState<string | null>(null);

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);
  const [shouldAutoFocus, setShouldAutoFocus] = useState(false);

  // Start time tracking for current quote
  const [quoteStartTime, setQuoteStartTime] = useState<number | null>(null);

  const isFetchingRef = useRef(false);

  // Derive Lock State
  const uniqueTiers = Array.from(new Set(LEVELS.map(l => l.tier)));
  const currentTierIndex = uniqueTiers.indexOf(currentLevel.tier);

  const polliwogIndex = uniqueTiers.indexOf('Polliwog');
  const isHardcoreLocked = currentTierIndex < polliwogIndex;

  const frogletIndex = uniqueTiers.indexOf('Froglet');
  const isArcadeLocked = currentTierIndex < frogletIndex;

  // Practice Lock: Require 20 matches to gather data
  const isPracticeLocked = testHistory.length < 20;

  // Gating Check
  const avgWpmVal = getAverageWPM(wpmHistory);
  const remediationCount = Object.keys(failedQuoteRepetitions).length;
  const { isGated, reason } = checkLevelProgress(userXP, avgWpmVal, mistakePool.length, remediationCount);

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_unlockedTiers', JSON.stringify(unlockedTiers)); }, [unlockedTiers]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_dailyStreak', dailyStreak.toString()); }, [dailyStreak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_smartQueue', JSON.stringify(smartPracticeQueue)); }, [smartPracticeQueue]);
  useEffect(() => { localStorage.setItem('frogType_charStats', JSON.stringify(charStats)); }, [charStats]);
  useEffect(() => { localStorage.setItem('frogType_userName', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('frogType_totalTime', totalTimePlayed.toString()); }, [totalTimePlayed]);
  useEffect(() => { localStorage.setItem('frogType_practiceLevel', practiceLevel.toString()); }, [practiceLevel]);
  useEffect(() => { localStorage.setItem('frogType_remediations', JSON.stringify(failedQuoteRepetitions)); }, [failedQuoteRepetitions]);

  // Game Mode Persistence & Lock Check
  useEffect(() => { 
      if (gameMode === 'HARDCORE' && isHardcoreLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'PRACTICE' && isPracticeLocked) {
          setGameMode('QUOTES');
      }
      if (gameMode === 'MINIGAMES' && isArcadeLocked) {
          setGameMode('QUOTES');
      }
      localStorage.setItem('frogType_gameMode', gameMode); 
  }, [gameMode, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setMechanicalPreset(settings.mechanicalSoundPreset);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.mechanicalSoundPreset, settings.ambientVolume, settings.musicConfig]);

  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;
    root.style.setProperty('--bg-body', theme.colors.background);
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });
    root.style.setProperty('--text-body', theme.colors.stone[800]);
  }, [settings.themeId]);

  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
      setQuoteStartTime(Date.now());
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Check Daily Streak on Mount
  useEffect(() => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      // If user hasn't visited today, check if streak should break
      if (lastVisit && lastVisit !== today) {
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);

          if (yesterday.toDateString() !== lastVisit) {
              // Streak broken if last visit was not yesterday
              setDailyStreak(0);
          }
      } else if (!lastVisit) {
          setDailyStreak(0);
      }
  }, []);

  const updateDailyStreakActivity = () => {
      const today = new Date().toDateString();
      const lastVisit = localStorage.getItem('frogType_lastVisitDate');

      if (lastVisit !== today) {
          // New day activity
          let newStreak = 1;
          if (lastVisit) {
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);
              if (yesterday.toDateString() === lastVisit) {
                  newStreak = dailyStreak + 1;
              }
          }
          setDailyStreak(newStreak);
          localStorage.setItem('frogType_lastVisitDate', today);

          // Toast for streak
          setNotificationQueue(prev => [...prev, {
              id: `daily_${Date.now()}`,
              title: "Daily Streak!",
              description: `You're on a ${newStreak} day streak.`,
              icon: <Flame className="w-5 h-5 text-orange-500" />,
              type: "INFO"
          }]);
      } else {
          // Already played today, ensure streak is at least 1 if it was 0
          if (dailyStreak === 0) {
              setDailyStreak(1);
              localStorage.setItem('frogType_lastVisitDate', today);
          }
      }
  };

  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;
    let pool = [...mistakePool];
    // Allow random selection including duplicates to reinforce learning
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    if (isFetchingRef.current) return;
    if (gameMode === 'MINIGAMES') return; 

    isFetchingRef.current = true;

    try {
      const level = getCurrentLevel(userXP);

      // 1. Fetch Standard Quotes
      const newQuotes = await fetchQuotes(5, completedQuotes, level.name, gameMode, practiceLevel, charStats, smartPracticeQueue);

      // 2. Inject Remediation Quotes (High Priority)
      // If we have failed quotes that need clearing, inject them.
      const pendingRemediations = Object.keys(failedQuoteRepetitions);

      if (pendingRemediations.length > 0 && gameMode === 'QUOTES') {
          // Shuffle remediations
          const toInject = pendingRemediations.sort(() => 0.5 - Math.random()).slice(0, 2);

          const injectionQuotes: Quote[] = toInject.map(text => ({
              text: text,
              source: "Remediation",
              author: `Repeat Required (${failedQuoteRepetitions[text]} left)`
          }));

          // Mix them in: 2 remediations + 3 new quotes
          const mixed = [...injectionQuotes, ...newQuotes.slice(0, 3)];
          // Shuffle again so it's not always first
          setQuotesQueue(prev => [...prev, ...mixed.sort(() => 0.5 - Math.random())]);
      } else {
          setQuotesQueue(prev => [...prev, ...newQuotes]);
      }

    } catch (error) {
      console.error("Failed to load quotes", error);
    } finally {
      isFetchingRef.current = false;
    }
  }, [completedQuotes, userXP, gameMode, practiceLevel, charStats, smartPracticeQueue, failedQuoteRepetitions]);

  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0 && gameMode !== 'MINIGAMES') {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3 && gameMode !== 'MINIGAMES') {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (currentQuote || gameMode === 'MINIGAMES') return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newNotifications: NotificationItem[] = [];
    const newUnlockIds: string[] = [];

    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, 
       maxStreak: Math.max(streak + 1, streak + 1),
       currentStreak: streak + 1,
       mode: gameMode,
       practiceLevel
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlockIds.push(ach.id);
               newNotifications.push({
                   id: ach.id,
                   title: ach.title,
                   description: ach.description,
                   icon: ach.icon,
                   type: 'ACHIEVEMENT'
               });
           }
       }
    });

    if (newUnlockIds.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlockIds]);
       setNotificationQueue(prev => [...prev, ...newNotifications]);
       soundEngine.playLevelUp(); 
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number, mistakes: string[], retryCount: number) => {
    let finalXp = xpCalc; 
    setShouldAutoFocus(true);

    // Update Time Played
    if (quoteStartTime) {
        const durationSec = Math.floor((Date.now() - quoteStartTime) / 1000);
        setTotalTimePlayed(prev => prev + durationSec);
    }

    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // --- REMEDIATION SUCCESS LOGIC ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        // Check if this quote was in the remediation list
        if (failedQuoteRepetitions[key] !== undefined) {
            setFailedQuoteRepetitions(prev => {
                const currentVal = prev[key];
                const newVal = currentVal - 1;
                const newObj = { ...prev };

                if (newVal <= 0) {
                    delete newObj[key];
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Redemption!",
                        description: "Failed quote mastered.",
                        icon: <RefreshCcw className="w-5 h-5 text-green-500" />,
                        type: 'INFO'
                    }]);
                } else {
                    newObj[key] = newVal;
                    setNotificationQueue(prevQ => [...prevQ, {
                        id: `remediate_${Date.now()}`,
                        title: "Progress Saved",
                        description: `${newVal} successful repetitions left.`,
                        icon: <RefreshCcw className="w-5 h-5 text-orange-500" />,
                        type: 'INFO'
                    }]);
                }
                return newObj;
            });
        }
    }

    // Fix Mistake Mode Logic - Updated to remove only one instance per successful type
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = currentQuote.text.split(' '); // Keep all instances
      setMistakePool(prev => {
          const newPool = [...prev];
          wordsFixed.forEach(fixedWord => {
              const idx = newPool.indexOf(fixedWord);
              if (idx > -1) newPool.splice(idx, 1);
          });
          return newPool;
      });
    }

    // --- SMART PRACTICE LOGIC (MASTERY UPDATE) ---
    if (currentQuote) {
        const quoteWords = currentQuote.text.split(/\s+/).map(w => w.replace(/[^a-zA-Z]/g, '').toLowerCase()).filter(w => w.length > 1);

        const runMistakes = new Set(mistakes.map(w => w.toLowerCase()));

        setSmartPracticeQueue(prevQueue => {
            const newQueue = [...prevQueue];
            let changed = false;

            quoteWords.forEach(qWord => {
                const index = newQueue.findIndex(pw => pw.word === qWord);

                if (index !== -1) {
                    if (runMistakes.has(qWord)) {
                        newQueue[index] = { ...newQueue[index], proficiency: 0, lastPracticed: Date.now() };
                        changed = true;
                    } else {
                        const newProficiency = newQueue[index].proficiency + 1;
                        if (newProficiency >= 3) {
                            newQueue.splice(index, 1);
                        } else {
                            newQueue[index] = { ...newQueue[index], proficiency: newProficiency, lastPracticed: Date.now() };
                        }
                        changed = true;
                    }
                }
            });

            return changed ? newQueue : prevQueue;
        });
    }

    // Practice Mode Level Up Logic
    if (gameMode === 'PRACTICE') {
        if (retryCount === 0 && mistakes.length === 0 && wpm > 30) {
            const nextLevel = practiceLevel + 1;
            setPracticeLevel(nextLevel);
            const newLetter = getPracticeLetter(nextLevel);

            setNotificationQueue(prev => [...prev, {
                id: `practice_level_${nextLevel}`,
                title: "Practice Level Up!",
                description: `Unlocked letter: ${newLetter}`,
                icon: <ArrowUpCircle className="w-5 h-5 text-frog-green" />,
                type: 'INFO'
            }]);

            setQuotesQueue([]);
        }
    }

    if (currentQuote && gameMode !== 'FIX_MISTAKE' && gameMode !== 'PRACTICE') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update History
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode,
      quoteText: currentQuote?.text || "",
      mistakes: mistakes,
      retryCount: retryCount
    };
    setTestHistory(prev => [...prev, newTestResult]);

    checkAchievements(wpm);

    // Calculate XP and Handle Gates/Unlocks
    handleXPGain(finalXp, avgWpm);

    setLastWpm(wpm);
    setCurrentQuote(null); 
    setQuoteStartTime(null);
  };

  const handleMiniGameOver = (score: number, xp: number, wave?: number) => {
      const gameName = activeMiniGame === 'SURVIVAL_SWAMP' ? 'Swamp Survival' 
        : activeMiniGame === 'SURVIVAL_ZOMBIE' ? 'Zombie Outbreak'
        : activeMiniGame === 'COSMIC_DEFENSE' ? 'Cosmic Defense'
        : 'Time Attack';

      const newTestResult: TestResult = {
          id: Date.now(),
          date: new Date().toISOString(),
          wpm: 0, 
          xpEarned: xp,
          mode: 'MINIGAMES',
          quoteText: `${gameName} - Score: ${score}${wave ? ` (Wave ${wave})` : ''}`,
          mistakes: [],
          retryCount: 0
      };
      setTestHistory(prev => [...prev, newTestResult]);

      handleXPGain(xp, getAverageWPM(wpmHistory));
      setNotificationQueue(prev => [...prev, {
          id: `survival_${Date.now()}`,
          title: "Arcade Run Complete",
          description: `Score: ${score} | +${xp} XP`,
          icon: <Skull className="w-5 h-5 text-red-500" />,
          type: 'INFO'
      }]);
  };

  const handleXPGain = (xpAmount: number, currentAvgWpm: number) => {
    const currentLevelObj = getCurrentLevel(userXP);
    const nextLevelObj = getNextLevel(currentLevelObj);
    let potentialXp = userXP + xpAmount;

    // Pass current remediation count to checkLevelProgress
    const currentRemediationCount = Object.keys(failedQuoteRepetitions).length;

    if (nextLevelObj && potentialXp >= nextLevelObj.minXP) {
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = currentAvgWpm < nextLevelObj.requiredWpm;

         const isEggInternal = currentLevelObj.tier === 'Egg' && nextLevelObj.tier === 'Egg';
         const isTierJump = currentLevelObj.tier !== nextLevelObj.tier;
         const isRemediationGated = isTierJump && currentRemediationCount > 0;

         if (!isEggInternal && (isMasteryGated || isSpeedGated || isRemediationGated)) {
            potentialXp = nextLevelObj.minXP - 1; 
         }
    }

    const newLevel = getCurrentLevel(potentialXp);

    // Check for Tier Unlocks
    if (!unlockedTiers.includes(newLevel.tier)) {
         setUnlockedTiers(prev => [...prev, newLevel.tier]);

         const newStations = RADIO_STATIONS.filter(s => s.tier === newLevel.tier);

         if (newStations.length > 0) {
             const musicNotifications: NotificationItem[] = newStations.map(s => ({
                id: `unlock_${s.id}`,
                title: 'New Station Unlocked',
                description: s.name,
                icon: <Radio className="w-5 h-5 text-stone-900" />,
                type: 'UNLOCK'
             }));
             setNotificationQueue(prev => [...prev, ...musicNotifications]);
         }
    }

    const prevLevel = getCurrentLevel(userXP);
    if (newLevel.tier !== prevLevel.tier && potentialXp >= newLevel.minXP) {
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#40D672', '#22c55e', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); 
          }, 300);
    }

    setUserXP(potentialXp);
    if (gameMode !== 'MINIGAMES') {
        setStreak(prev => prev + 1);
    }

    // Update Daily Streak
    updateDailyStreakActivity();
  };

  const handleQuoteFail = () => {
    // --- REMEDIATION TRIGGER ---
    if (gameMode === 'QUOTES' && currentQuote) {
        const key = currentQuote.text;
        setFailedQuoteRepetitions(prev => {
            // Strict: Failing resets debt to 3.
            return { ...prev, [key]: 3 }; 
        });

        setNotificationQueue(prev => [...prev, {
            id: `fail_${Date.now()}`,
            title: "Quote Failed",
            description: "You must now pass this quote 3 times to proceed.",
            icon: <AlertTriangle className="w-5 h-5 text-red-500" />,
            type: 'INFO'
        }]);
    }

    setStreak(0);
  };

  const handleMistake = (word?: string, expectedChar?: string, typedChar?: string) => {
    let penaltyMultiplier = 0.85; 

    if (gameMode === 'HARDCORE') {
        penaltyMultiplier = 0.5;
    } else if (gameMode === 'FIX_MISTAKE') {
        penaltyMultiplier = 0.95;
    }

    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    // Note: streak is reset in handleQuoteFail for consistency when the entire quote fails
    // But mistakes in 'QUOTES' mode cause instant failure via TypingArea logic which calls onFail.
    // However, onMistake is called *before* onFail in TypingArea.
    // So we reset streak here too just in case.
    setStreak(0);

    // Track Words for FIX MISTAKE mode (Classic) - REQUIRE 3 REPETITIONS TO CLEAR
    if (word && word.length > 1) {
       setMistakePool(prev => {
         // Reset this word's debt to 3 if mistakenly typed
         const clean = prev.filter(w => w !== word);
         return [...clean, word, word, word];
       });

       const cleanWord = word.toLowerCase().replace(/[^a-z]/g, '');
       if (cleanWord.length > 1) {
           setSmartPracticeQueue(prev => {
               const idx = prev.findIndex(p => p.word === cleanWord);
               if (idx !== -1) {
                   const updated = [...prev];
                   updated[idx] = { ...updated[idx], proficiency: 0, lastPracticed: Date.now() };
                   return updated;
               } else {
                   return [...prev, { word: cleanWord, proficiency: 0, lastPracticed: Date.now() }];
               }
           });
       }
    }

    // Track Specific Characters for Smart Practice
    if (expectedChar && /[a-zA-Z]/.test(expectedChar)) {
        const lowerChar = expectedChar.toLowerCase();
        setCharStats(prev => {
            const currentCount = prev[lowerChar] || 0;
            return { ...prev, [lowerChar]: currentCount + 1 };
        });
    }
  };

  const handlePracticeFromHistory = (mistakes: string[]) => {
      setMistakePool(prev => {
          const newSet = new Set([...prev, ...mistakes]);
          return Array.from(newSet);
      });
      switchMode('FIX_MISTAKE');
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const cycleReadAhead = () => {
      const levels: ReadAheadLevel[] = ['NONE', 'FOCUS', 'ULTRA', 'BLIND'];
      const currentIndex = levels.indexOf(settings.readAheadLevel);
      const nextIndex = (currentIndex + 1) % levels.length;
      setSettings({ ...settings, readAheadLevel: levels[nextIndex] });
      soundEngine.playKeypress(); // Feedback
  };

  const switchMode = useCallback((mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    if (mode === 'HARDCORE' && isHardcoreLocked) return;
    if (mode === 'PRACTICE' && isPracticeLocked) return;
    if (mode === 'MINIGAMES' && isArcadeLocked) return;

    setShouldAutoFocus(false);

    if (mode === 'MINIGAMES') {
        setIsMiniGameMenuOpen(true);
        setActiveMiniGame(null);
    } else {
        setIsMiniGameMenuOpen(false);
        setActiveMiniGame(null);
        setGameMode(mode);
        setQuotesQueue([]); 
        setCurrentQuote(null); 
    }
  }, [mistakePool.length, isHardcoreLocked, isPracticeLocked, isArcadeLocked]);

  const handleMiniGameSelect = (gameId: string) => {
      setGameMode('MINIGAMES');
      setActiveMiniGame(gameId);
      setIsMiniGameMenuOpen(false);
  };

  const handleRequestNextQuote = async () => {
      setCurrentQuote(null);
      setQuoteStartTime(null);
  };

  const clearToast = useCallback(() => {
    setNotificationQueue(prev => prev.slice(1));
  }, []);

  const getReadAheadConfig = () => {
      switch(settings.readAheadLevel) {
          case 'FOCUS': return { label: 'Focus', color: 'text-frog-green', bg: 'bg-frog-100', bonus: '+10%' };
          case 'ULTRA': return { label: 'Ultra', color: 'text-purple-600', bg: 'bg-purple-100', bonus: '+20%' };
          case 'BLIND': return { label: 'Blind', color: 'text-red-600', bg: 'bg-red-100', bonus: '+30%' };
          default: return { label: 'Off', color: 'text-stone-400', bg: 'hover:bg-stone-100', bonus: '' };
      }
  };
  const raConfig = getReadAheadConfig();

  const renderMiniGame = () => {
      if (activeMiniGame === 'SURVIVAL_SWAMP') {
          return (
              <SurvivalGame 
                  variant="SWAMP"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'SURVIVAL_ZOMBIE') {
          return (
              <SurvivalGame 
                  variant="ZOMBIE"
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp, 0)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'TIME_ATTACK') {
          return (
              <TimeAttackGame
                  onGameOver={(score, xp) => handleMiniGameOver(score, xp)} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      if (activeMiniGame === 'COSMIC_DEFENSE') {
          return (
              <CosmicDefenseGame
                  onGameOver={handleMiniGameOver} 
                  onExit={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} 
              />
          );
      }
      // Fallback
      return (
          <div className="text-stone-400 p-10 text-center">
              Unknown Game Mode
              <button onClick={() => { setIsMiniGameMenuOpen(true); setActiveMiniGame(null); }} className="block mx-auto mt-4 text-frog-green underline">Return</button>
          </div>
      );
  };

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      <div className="sticky top-0 z-40 flex flex-col shadow-sm transition-all">
          <header className="w-full bg-stone-50/95 backdrop-blur-md border-b border-stone-200 px-6 py-3">
            <div className="max-w-[1400px] mx-auto flex flex-col md:flex-row items-center justify-between gap-4">

              <div className="flex flex-col md:flex-row items-center gap-6 w-full md:w-auto">
                <div className="flex flex-col items-center md:items-start flex-shrink-0">
                  <h1 className="text-xl font-black text-frog-green tracking-tight flex items-center gap-2">
                    <span className="text-2xl">🐸</span> Frog Type
                  </h1>
                </div>

                <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50 overflow-x-auto max-w-full">
                  <button 
                      onClick={() => switchMode('QUOTES')}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${gameMode === 'QUOTES' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      <BookOpen className="w-3.5 h-3.5" /> Quotes
                  </button>
                  <button 
                      onClick={() => switchMode('PRACTICE')}
                      disabled={isPracticeLocked}
                      title={isPracticeLocked ? `Calibrating skill profile... (${testHistory.length}/20)` : "Smart Practice Mode"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame 
                            ? 'bg-white text-frog-green shadow-sm ring-1 ring-stone-200' 
                            : isPracticeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100 border border-stone-200' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isPracticeLocked ? <Lock className="w-3.5 h-3.5" /> : <Keyboard className="w-3.5 h-3.5" />} 
                      Practice
                  </button>
                  <button 
                      onClick={() => switchMode('HARDCORE')}
                      disabled={isHardcoreLocked}
                      title={isHardcoreLocked ? "Unlocks at Polliwog level" : "High risk, high reward"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'HARDCORE' && !isMiniGameMenuOpen && !activeMiniGame
                          ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' 
                          : isHardcoreLocked 
                              ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                              : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isHardcoreLocked ? <Lock className="w-3.5 h-3.5" /> : <Skull className="w-3.5 h-3.5" />} 
                      Hardcore
                  </button>
                  <button 
                      onClick={() => switchMode('MINIGAMES')}
                      disabled={isArcadeLocked}
                      title={isArcadeLocked ? "Unlocks at Froglet level" : "Minigames & Boss Battles"}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'MINIGAMES' || isMiniGameMenuOpen || activeMiniGame 
                            ? 'bg-purple-100 text-purple-600 shadow-sm ring-1 ring-purple-200' 
                            : isArcadeLocked 
                                ? 'opacity-50 cursor-not-allowed text-stone-400 bg-stone-100' 
                                : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
                  >
                      {isArcadeLocked ? <Lock className="w-3.5 h-3.5" /> : <Gamepad2 className="w-3.5 h-3.5" />} 
                      Arcade
                  </button>
                  <button 
                      onClick={() => switchMode('FIX_MISTAKE')}
                      disabled={mistakePool.length === 0}
                      className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 
                        ${gameMode === 'FIX_MISTAKE' && !isMiniGameMenuOpen && !activeMiniGame ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                        ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                        ${isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' ? 'ring-2 ring-orange-200 bg-orange-200 text-orange-900 animate-pulse shadow-[0_0_10px_rgba(253,186,116,0.6)]' : ''}
                      `}
                      title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
                  >
                      <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
                  </button>
                </div>
              </div>

              <div className="flex items-center gap-1.5 shrink-0">
                   <button 
                     onClick={cycleReadAhead}
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 group relative ${raConfig.bg} ${raConfig.color}`}
                     title={`Read Ahead: ${raConfig.label} (${raConfig.bonus ? raConfig.bonus + ' XP' : 'No Bonus'})`}
                   >
                      {settings.readAheadLevel === 'NONE' ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                      {raConfig.bonus && (
                          <span className="absolute -top-1 -right-1 bg-frog-green text-white text-[8px] px-1 rounded-full font-bold">
                              {raConfig.bonus.replace('+','')}
                          </span>
                      )}
                   </button>

                   <button 
                     onClick={toggleAchievements} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isAchievementsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Achievements"
                   >
                      <Award className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleTheme} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isThemeOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Themes"
                   >
                      <Palette className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleStats} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isStatsOpen ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Statistics & History"
                   >
                      <TrendingUp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleHelp} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="How to Play"
                   >
                      <CircleHelp className="w-5 h-5" />
                   </button>
                   <button 
                     onClick={toggleMusic} 
                     className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2 ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-green' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                     title="Background Music"
                   >
                      <Music className="w-5 h-5" />
                   </button>
                   <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors focus:outline-none focus:ring-2 focus:ring-frog-green focus:ring-offset-2">
                      <SettingsIcon className="w-5 h-5" />
                   </button>
              </div>

            </div>
          </header>

          <div className="w-full bg-white/95 backdrop-blur-md border-b border-stone-200 px-6 py-2">
               <div className="max-w-[1400px] mx-auto">
                   <ProgressBar 
                     xp={userXP} 
                     avgWpm={getAverageWPM(wpmHistory)} 
                     mistakeCount={mistakePool.length} 
                     remediationCount={Object.keys(failedQuoteRepetitions).length}
                   />
               </div>
          </div>
      </div>

      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full flex flex-col items-center justify-center min-h-[60vh]">
          {isGated && reason === 'MASTERY' && gameMode !== 'FIX_MISTAKE' ? (
              <div className="mb-8 w-full max-w-2xl relative overflow-hidden bg-orange-50 border-2 border-orange-200 p-8 rounded-3xl shadow-xl flex flex-col items-center text-center gap-6 animate-in slide-in-from-top-5 duration-500 z-50">
                  <div className="absolute top-0 left-0 w-full h-2 bg-orange-400/20"></div>

                  <div className="p-4 bg-orange-100 rounded-full text-orange-500 ring-4 ring-orange-50">
                      <AlertTriangle className="w-10 h-10" />
                  </div>

                  <div className="space-y-2">
                      <h3 className="text-3xl font-black text-orange-900 uppercase tracking-tight">Evolution Blocked</h3>
                      <p className="text-orange-800 font-medium text-lg max-w-md leading-relaxed">
                          You cannot evolve to the next level until you prove mastery over your mistakes.
                      </p>
                      <div className="bg-orange-100/50 px-4 py-2 rounded-lg border border-orange-200 inline-block">
                          <p className="text-orange-700 text-sm font-bold">
                              Requirement: Correctly type {mistakePool.length} words (3x each)
                          </p>
                      </div>
                  </div>

                  <button 
                    onClick={() => switchMode('FIX_MISTAKE')}
                    className="mt-2 px-10 py-4 bg-orange-500 hover:bg-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-3 ring-4 ring-orange-500/20"
                  >
                      <RefreshCcw className="w-6 h-6" />
                      FIX MISTAKES
                  </button>
              </div>
          ) : (
             <>
                {isGated && reason === 'REMEDIATION' && gameMode === 'QUOTES' && (
                    <div className="mb-8 relative group overflow-hidden bg-orange-500 text-white px-8 py-4 rounded-3xl shadow-xl shadow-orange-200 flex items-center gap-5 transition-all transform hover:-translate-y-1 hover:shadow-2xl ring-4 ring-orange-100 animate-pulse z-50 cursor-default">
                        <div className="bg-white/20 p-3 rounded-full shadow-inner">
                            <RefreshCcw className="w-8 h-8 text-white fill-white/20" />
                        </div>
                        <div className="text-left">
                            <div className="font-black text-xl uppercase tracking-tight leading-none text-white">Tier Gated!</div>
                            <div className="font-medium text-sm text-orange-100 mt-1">
                                Remediate <span className="font-black text-white border-b-2 border-orange-300/50">{Object.keys(failedQuoteRepetitions).length} failed quotes</span>
                            </div>
                        </div>
                    </div>
                )}

                {gameMode === 'PRACTICE' && !isMiniGameMenuOpen && !activeMiniGame && (
                    <div className="w-full flex flex-col items-center">
                        {smartPracticeQueue.length > 0 && (
                            <div className="mb-4 flex items-center gap-2 text-stone-500 text-xs font-bold uppercase tracking-wide bg-stone-100 px-4 py-1.5 rounded-full">
                                <Brain className="w-4 h-4 text-purple-500" />
                                <span>Smart Queue: {smartPracticeQueue.length} words to master</span>
                            </div>
                        )}
                        <PracticeProgress level={practiceLevel} />
                    </div>
                )}

                {isMiniGameMenuOpen ? (
                    <MiniGameMenu 
                        onSelect={handleMiniGameSelect} 
                        onBack={() => setIsMiniGameMenuOpen(false)} 
                    />
                ) : activeMiniGame ? (
                    renderMiniGame()
                ) : (
                   <>
                      {loading && !currentQuote ? (
                          <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
                          <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                          <p className="font-mono text-xs">
                              Hatching wisdom...
                          </p>
                          </div>
                      ) : currentQuote ? (
                          <TypingArea 
                          quote={currentQuote} 
                          onComplete={handleQuoteComplete} 
                          onFail={handleQuoteFail}
                          onMistake={handleMistake}
                          onRequestNewQuote={handleRequestNextQuote}
                          streak={streak}
                          ghostWpm={getAverageWPM(wpmHistory)}
                          settings={settings}
                          gameMode={gameMode}
                          onInteract={() => setIsMusicOpen(false)}
                          autoFocus={shouldAutoFocus}
                          />
                      ) : (
                          <div className="flex flex-col items-center justify-center text-stone-400">
                          <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-green" />
                          <p className="font-mono text-xs">Fetching wisdom...</p>
                          </div>
                      )}
                   </>
                )}
             </>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        notifications={notificationQueue}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
        onPractice={handlePracticeFromHistory}
        totalTime={totalTimePlayed}
        joinDate={joinDate}
        streak={dailyStreak} 
        userName={userName}
        setUserName={setUserName}
        completedTestsCount={testHistory.length}
      />

      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
        userXP={userXP}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';

export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  tier: string; // The major rank group (e.g. 'Egg', 'Tadpole')
  minXP: number;
  color: string;
  shade: string;
  requiredWpm: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export interface TestResult {
  id: number;
  date: string;
  wpm: number;
  xpEarned: number;
  mode: GameMode;
  quoteText: string;      // New: Store the text typed
  mistakes: string[];     // New: Store specific words missed
  retryCount: number;     // New: Store attempts needed
}

export type MusicSource = 'NONE' | 'YOUTUBE' | 'SPOTIFY' | 'GENERATED' | 'SUNO';

export interface MusicConfig {
  source: MusicSource;
  presetId: string;
}

export type MechanicalSoundPreset = 'THOCK' | 'CLICKY' | 'BUBBLE' | 'TYPEWRITER';

export type ReadAheadLevel = 'NONE' | 'FOCUS' | 'ULTRA' | 'BLIND';

export interface Settings {
  ghostEnabled: boolean;
  readAheadLevel: ReadAheadLevel; // Changed from boolean
  sfxEnabled: boolean;
  mechanicalSoundEnabled: boolean; // Toggle for typing sounds
  mechanicalSoundPreset: MechanicalSoundPreset; // Sound profile
  ambientVolume: number; // Volume for GENERATED sources (Brown Noise, Piano, etc.)
  musicConfig: MusicConfig;
  themeId: string; // New: Selected Theme ID
  autoStartMusic: boolean; // Control whether music starts automatically on load
}

export type GameMode = 'QUOTES' | 'HARDCORE' | 'XWORDS' | 'XQUOTES' | 'PRACTICE' | 'MINIGAMES';

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

export interface Theme {
  id: string;
  name: string;
  description: string;
  minTier: string; // Tier required to unlock (e.g. 'Tadpole')
  colors: {
    frog: Record<number, string>; // 50-900
    stone: Record<number, string>; // 50-900 (Used for neutrals)
    background: string;
  };
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  category: 'SPEED' | 'STREAK' | 'VOLUME' | 'MASTERY' | 'HIDDEN' | 'PRACTICE';
  condition: (stats: { wpm: number; totalQuotes: number; maxStreak: number; currentStreak: number; mode: GameMode; practiceLevel: number }) => boolean;
}

export interface NotificationItem {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  type: 'ACHIEVEMENT' | 'UNLOCK' | 'INFO';
}

export interface PracticeWord {
  word: string;
  proficiency: number; // 0 to 3 (3 = Mastered)
  lastPracticed: number;
}

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { Quote, GameStatus, Settings, GameMode } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { soundEngine } from '../utils/soundEngine';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Sparkles, ArrowUp, Lock, XCircle, AlertTriangle, ArrowRight } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number, mistakes: string[], retryCount: number) => void;
  onFail: () => void;
  onMistake: (word?: string, expectedChar?: string, typedChar?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
  onInteract?: () => void;
  autoFocus?: boolean;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode,
  onInteract,
  autoFocus = false
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(autoFocus);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);
  const [capsLock, setCapsLock] = useState(false);
  const [isShiftPressed, setIsShiftPressed] = useState(false);

  // Tracking Stats
  const [sessionMistakes, setSessionMistakes] = useState(0);
  const [sessionMistakeWords, setSessionMistakeWords] = useState<string[]>([]);
  const [retryCount, setRetryCount] = useState(0);

  // Enhanced Error Tracking
  const [lastError, setLastError] = useState<{ 
      expectedChar: string, 
      typedChar: string, 
      index: number,
      expectedWord: string,
      typedWordPart: string 
  } | null>(null);

  // Smooth Caret State
  const [caretPos, setCaretPos] = useState({ left: 0, top: 0, height: 24, opacity: 0 });

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const textContainerRef = useRef<HTMLDivElement>(null);
  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const retryButtonRef = useRef<HTMLButtonElement>(null);

  // Sync Settings with Engine
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
  }, [settings.sfxEnabled]);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0);
    setSessionMistakeWords([]);
    setRetryCount(0);
    setLastError(null);

    // Auto-focus logic: If we are "focused" (e.g. from Next button), ensure the DOM element gets focus
    // We use a timeout to allow the render cycle to enable the textarea (since status changed to IDLE)
    if (isFocused) {
        setTimeout(() => {
            inputRef.current?.focus();
        }, 10);
    }
  }, [quote]); // Removed isFocused to prevent reset on blur/focus

  // Focus management for buttons when game ends
  useEffect(() => {
    if (status === GameStatus.COMPLETED) {
        setTimeout(() => nextButtonRef.current?.focus(), 50);
    } else if (status === GameStatus.FAILED) {
        setTimeout(() => retryButtonRef.current?.focus(), 50);
    }
  }, [status]);

  // Handlers wrapped in useCallback for stable dependencies
  const handleRetry = useCallback(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setSessionMistakes(0); 
    setLastError(null);
    setRetryCount(prev => prev + 1);
    setIsFocused(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }, []);

  const handleNext = useCallback(() => {
    const isPerfectMaster = retryCount === 0 && sessionMistakes === 0;
    const xp = calculateXP(wpm, quote.text.length, streak, isPerfectMaster, settings.readAheadLevel);
    // Ensure we stay focused for the next quote to avoid the "Click to Start" overlay
    setIsFocused(true);
    onComplete(xp, wpm, sessionMistakeWords, retryCount);
  }, [onComplete, wpm, quote.text.length, streak, retryCount, sessionMistakes, sessionMistakeWords, settings.readAheadLevel]);

  // Caps Lock & Shift Detection
  useEffect(() => {
    const checkCapsLock = (e: KeyboardEvent | MouseEvent) => {
      if (e.getModifierState) {
        setCapsLock(e.getModifierState('CapsLock'));
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(true);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === 'Shift') setIsShiftPressed(false);
    };

    window.addEventListener('keydown', checkCapsLock as any);
    window.addEventListener('keyup', checkCapsLock as any);
    window.addEventListener('click', checkCapsLock as any);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', checkCapsLock as any);
      window.removeEventListener('keyup', checkCapsLock as any);
      window.removeEventListener('click', checkCapsLock as any);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (status === GameStatus.COMPLETED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleNext();
        }
        return;
      }

      if (status === GameStatus.FAILED) {
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (!isFocused) {
        if (e.key === 'Tab') return;

        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status, handleNext, handleRetry]);

  // Smooth Caret Calculation
  useLayoutEffect(() => {
    const updateCaret = () => {
        if (!textContainerRef.current) return;

        let targetEl: HTMLElement | null = null;
        let left = 0;
        let top = 0;
        let height = 0;

        if (input.length < quote.text.length) {
            // Find current char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            }
        } else {
            // End of text, position after last char
            targetEl = textContainerRef.current.querySelector(`[data-index="${input.length - 1}"]`);
            if (targetEl) {
                left = targetEl.offsetLeft + targetEl.offsetWidth;
                top = targetEl.offsetTop;
                height = targetEl.offsetHeight;
            } else if (quote.text.length === 0) {
                 // Empty quote fallback
                 left = 0;
                 top = 0;
                 height = 24; 
            }
        }

        // Handle visual adjustment for empty state or start
        if (input.length === 0 && quote.text.length > 0) {
             const firstEl = textContainerRef.current.querySelector(`[data-index="0"]`) as HTMLElement;
             if (firstEl) {
                 left = firstEl.offsetLeft;
                 top = firstEl.offsetTop;
                 height = firstEl.offsetHeight;
             }
        }

        setCaretPos({ 
            left, 
            top, 
            height: height || 32, // Default height fallback
            opacity: isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED ? 1 : 0
        });
    };

    updateCaret();
    window.addEventListener('resize', updateCaret);
    return () => window.removeEventListener('resize', updateCaret);
  }, [input, quote, isFocused, status, settings.readAheadLevel]); // Recalculate on any change affecting layout

  const handleFocus = () => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end); 
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED || status === GameStatus.FAILED) return;

    const val = e.target.value;
    const prevLen = input.length;

    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    if (val.length > prevLen) {
        soundEngine.playKeypress();
    }

    // --- Instant Fail Check (All Modes) ---
    if (val.length > 0) {
      if (!quote.text.startsWith(val)) {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();

        const mistakeIndex = val.length - 1;
        const expectedChar = quote.text[mistakeIndex];
        const typedChar = val[mistakeIndex];

        // --- Calculate Word Context ---
        const wordStart = quote.text.lastIndexOf(' ', mistakeIndex) + 1;
        let wordEnd = quote.text.indexOf(' ', mistakeIndex);
        if (wordEnd === -1) wordEnd = quote.text.length;

        const expectedWord = quote.text.substring(wordStart, wordEnd);
        const typedWordPart = val.substring(wordStart);
        const cleanWord = expectedWord.replace(/[.,;!?]/g, '');

        setLastError({ 
            expectedChar, 
            typedChar, 
            index: mistakeIndex,
            expectedWord,
            typedWordPart
        });

        onMistake(cleanWord, expectedChar, typedChar);

        // Track locally for history
        setSessionMistakes(prev => prev + 1);
        if (cleanWord && !sessionMistakeWords.includes(cleanWord)) {
            setSessionMistakeWords(prev => [...prev, cleanWord]);
        }
        return;
      }
    }

    setInput(val);

    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        soundEngine.playSuccess(); 
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        soundEngine.playError(); 
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const getReadAheadState = (index: number) => {
    if (settings.readAheadLevel === 'NONE' || status === GameStatus.IDLE) return { isHidden: false, isHighlighted: false };

    const text = quote.text;
    const caret = input.length;

    let currentWordStart = text.lastIndexOf(' ', caret - 1);
    currentWordStart = currentWordStart === -1 ? 0 : currentWordStart + 1;

    let currentWordEnd = text.indexOf(' ', caret);
    if (currentWordEnd === -1) currentWordEnd = text.length;

    // --- LEVEL 1: FOCUS ---
    if (index >= currentWordStart && index < currentWordEnd) {
        return { isHidden: true, isHighlighted: false };
    }

    // --- LEVEL 2: ULTRA ---
    if (settings.readAheadLevel === 'ULTRA' || settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        if (index >= nextWordStart && index < nextWordEnd) {
            return { isHidden: true, isHighlighted: false }; 
        }
    }

    // --- LEVEL 3: BLIND ---
    if (settings.readAheadLevel === 'BLIND') {
        let nextWordStart = currentWordEnd + 1;
        let nextWordEnd = text.indexOf(' ', nextWordStart);
        if (nextWordEnd === -1) nextWordEnd = text.length;

        let secondNextStart = nextWordEnd + 1;
        let secondNextEnd = text.indexOf(' ', secondNextStart);
        if (secondNextEnd === -1) secondNextEnd = text.length;

        if (index >= secondNextStart && index < secondNextEnd) {
             return { isHidden: true, isHighlighted: false };
        }
    }

    // Highlight next visible word
    if (index > currentWordEnd) { 
        let highlightStart = currentWordEnd + 1;
        if (settings.readAheadLevel === 'ULTRA') {
             let skip1 = text.indexOf(' ', highlightStart);
             if (skip1 !== -1) highlightStart = skip1 + 1;
             else highlightStart = text.length; 
        } else if (settings.readAheadLevel === 'BLIND') {
             let skip1 = text.indexOf(' ', highlightStart);
             let skip2 = skip1 !== -1 ? text.indexOf(' ', skip1 + 1) : -1;
             if (skip2 !== -1) highlightStart = skip2 + 1;
             else highlightStart = text.length;
        }

        let highlightEnd = text.indexOf(' ', highlightStart);
        if (highlightEnd === -1) highlightEnd = text.length;

        if (index >= highlightStart && index < highlightEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const getTextColor = () => {
     if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') return 'text-red-400/50';
        return 'text-red-300';
     }
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = getTextColor(); 
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      if (index < input.length) {
        if (input[index] === char) {
          // Use frog-green for completed text
          colorClass = 'text-frog-green'; 
        } else {
          colorClass = 'text-red-500 bg-red-100'; 
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-green font-bold';
              bgClass = 'bg-green-100/50';
          }
      }

      if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} data-index={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}

            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (status === GameStatus.FAILED) {
        if (gameMode === 'HARDCORE') {
            return 'bg-red-900/20 border-red-900/50 shadow-[0_0_40px_rgba(220,38,38,0.1)]';
        }
        return 'bg-red-50 border-red-200 shadow-inner';
    }

    if (gameMode === 'HARDCORE') {
        return 'bg-neutral-900 border-neutral-800 text-neutral-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'XWORDS' || gameMode === 'XQUOTES') {
        return 'bg-red-50 border-red-100';
    }

    // Light gray background for container
    return 'bg-stone-50 border-stone-200 overflow-hidden';
  };

  // Dynamic Text Sizing - Standard/Cozy sizing logic
  const getFontSizeClass = () => {
    const len = quote.text.length;
    // Standard sizes, scaled down if necessary, never massive
    if (len < 100) return 'text-xl md:text-2xl leading-relaxed';
    if (len < 200) return 'text-lg md:text-xl leading-relaxed';
    return 'text-base md:text-lg leading-relaxed';
  };

  const isPerfectMasterPotential = retryCount === 0 && sessionMistakes === 0;

  return (
    <div 
      className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Perfect Master Indicator */}
      {isPerfectMasterPotential && status === GameStatus.PLAYING && (
        <div className="absolute -top-8 left-1/2 transform -translate-x-1/2 flex items-center gap-1 text-xs font-bold text-frog-green animate-pulse">
          <Sparkles className="w-3 h-3" /> Perfect Master Potential (1.5x Bonus)
        </div>
      )}

      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-16 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${isFocused && status !== GameStatus.FAILED && status !== GameStatus.COMPLETED ? 'ring-2 ring-frog-green/50 ring-offset-2 ring-offset-bg-body' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-green/20 bg-green-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && (
          <div 
            onClick={handleFocus}
            className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-sm cursor-pointer rounded-[3rem] border-2 border-dashed border-frog-green/50 hover:border-frog-green transition-all"
          >
            <div className="text-center animate-bounce text-frog-green">
              <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
              <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
            </div>
          </div>
        )}

        {/* SUCCESS MODAL */}
        {status === GameStatus.COMPLETED && (
          <div 
            className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer"
            onClick={handleNext}
          >
             <div 
                className="bg-stone-50/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-stone-200 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-6 min-w-[280px] cursor-default"
                onClick={(e) => e.stopPropagation()} 
             >
                <div className="text-frog-green font-black text-xl tracking-tight flex items-center gap-2">
                   <Award className="w-6 h-6" /> Quote Complete!
                </div>

                <div className="grid grid-cols-2 gap-x-12 gap-y-6 w-full">
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Time</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                        {endTime && startTime ? ((endTime - startTime) / 1000).toFixed(1) : '0.0'}s
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Speed</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">{wpm} <span className="text-xs text-stone-400 font-sans font-medium">WPM</span></span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">Retries</span>
                      <span className="font-mono font-bold text-2xl text-stone-700">
                          {retryCount}
                      </span>
                   </div>
                   <div className="flex flex-col items-center">
                      <span className="text-[10px] uppercase font-bold text-stone-400 tracking-widest mb-1">XP Earned</span>
                      <span className="font-mono font-bold text-2xl text-frog-green">
                        +{calculateXP(wpm, quote.text.length, streak, retryCount === 0 && sessionMistakes === 0, settings.readAheadLevel) * (gameMode === 'HARDCORE' ? 5 : 1)}
                      </span>
                   </div>
                </div>

                <button 
                  ref={nextButtonRef}
                  onClick={handleNext}
                  className={`flex items-center gap-2 px-8 py-3 rounded-full transition shadow-lg font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-offset-2 w-full justify-center
                    bg-frog-green text-white hover:bg-green-500 shadow-green-200/50 focus:ring-frog-green
                  `}
                >
                   Next Quote <Award className="w-4 h-4" />
                </button>
             </div>
          </div>
        )}

        {/* FAILED MODAL (Retry Screen) */}
        {status === GameStatus.FAILED && (
          <div 
            className="absolute inset-0 z-40 flex items-center justify-center bg-stone-900/10 backdrop-blur-sm rounded-[3rem] cursor-pointer"
            onClick={handleRetry}
          >
             <div 
                className="bg-white p-6 rounded-3xl shadow-2xl border border-stone-100 animate-in zoom-in-95 fade-in duration-300 flex flex-col items-center gap-4 min-w-[260px] cursor-default"
                onClick={(e) => e.stopPropagation()} 
             >
                <div className="text-red-500 font-black text-xl tracking-tight flex items-center gap-2">
                   <XCircle className="w-6 h-6" /> Run Failed
                </div>

                {/* Compact Error Box */}
                <div className="w-full bg-red-50 p-3 rounded-xl border border-red-100 flex flex-col items-center gap-1">
                    {lastError ? (
                        <>
                            <div className="text-[10px] font-bold text-red-400 uppercase tracking-wider">Mistake</div>
                            <div className="flex items-center gap-3 font-mono text-base">
                                 <span className="text-red-500 font-medium" title="You Typed">{lastError.typedWordPart}</span>
                                 <ArrowRight className="w-3.5 h-3.5 text-stone-300" />
                                 <span className="text-frog-green font-bold" title="Expected">{lastError.expectedWord}</span>
                            </div>
                        </>
                    ) : (
                        <span className="text-stone-400 italic text-xs">Unknown Error</span>
                    )}
                </div>

                {/* Compact Stats */}
                <div className="flex w-full justify-between gap-4 px-2">
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Progress</span>
                        <span className="font-mono font-bold text-lg text-stone-700">
                            {Math.floor((input.length / quote.text.length) * 100)}%
                        </span>
                     </div>
                     <div className="w-px bg-stone-100"></div>
                     <div className="flex flex-col items-center">
                        <span className="text-[9px] uppercase font-bold text-stone-400 tracking-wider">Speed</span>
                        <span className="font-mono font-bold text-lg text-stone-700">{wpm}</span>
                     </div>
                </div>

                <button 
                  ref={retryButtonRef}
                  onClick={handleRetry}
                  className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-red-500 text-white hover:bg-red-600 rounded-xl transition shadow-lg shadow-red-200/50 font-bold text-xs tracking-wide uppercase focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 transform hover:-translate-y-0.5"
                >
                  <RotateCcw className="w-3.5 h-3.5" /> Try Again
                </button>
             </div>
          </div>
        )}

        <div className="absolute top-4 left-0 right-0 flex justify-center gap-2 z-30 select-none pointer-events-none">
            {capsLock && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-orange-100 text-orange-600 rounded-full text-[10px] font-bold tracking-widest border border-orange-200 shadow-sm animate-pulse">
                <Lock className="w-3 h-3" /> CAPS LOCK
              </div>
            )}
            {isShiftPressed && (
               <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-[10px] font-bold tracking-widest border border-blue-100 shadow-sm">
                <ArrowUp className="w-3 h-3" /> SHIFT
              </div>
            )}
        </div>

        <div className="absolute top-10 left-0 right-0 px-10 md:px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans z-10 text-stone-500">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3.5 h-3.5"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadLevel !== 'NONE' && <span className="text-frog-green flex items-center gap-1"><EyeOff className="w-3.5 h-3.5"/> {settings.readAheadLevel}</span>}
          </div>
          <span className="text-right max-w-[200px] truncate">{quote.author}</span>
        </div>

        {/* Text Container with Caret and Dynamic Font */}
        <div 
          ref={textContainerRef}
          className={`font-mono tracking-wide break-words whitespace-pre-wrap mb-12 mt-10 relative z-10 outline-none select-none ${getTextColor()} ${getFontSizeClass()}`}
          onClick={handleFocus}
        >
          {/* Smooth Caret with Frog Green - Animation Disabled */}
          <div 
             className="absolute bg-frog-green w-[3px] rounded-full transition-all duration-100 ease-out z-20 pointer-events-none caret-blink shadow-[0_0_10px_rgba(64,214,114,0.5)]"
             style={{ 
                 left: caretPos.left - 1, 
                 top: caretPos.top + 2, 
                 height: caretPos.height - 4,
                 opacity: caretPos.opacity
             }}
          />
          {renderText()}
        </div>

        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => {
              setIsFocused(true);
              onInteract?.();
          }}
          onKeyDown={(e) => {
              if (e.key === 'Enter') {
                  e.preventDefault();
              }
          }}
          onPaste={(e) => e.preventDefault()}
          onCopy={(e) => e.preventDefault()}
          onDrop={(e) => e.preventDefault()}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        <div className="absolute bottom-10 left-0 right-0 px-10 md:px-20 flex justify-between items-end select-none z-10">
           <div className="flex items-center gap-10 text-stone-400 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-xl opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[10px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-xl flex items-center gap-1.5 font-sans">
                        <Flame className={`w-4 h-4 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>
        </div>
      </div>

      <div className="text-center mt-8 h-4 text-stone-400 text-xs font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? 
            <span className="text-red-400">
                {gameMode === 'HARDCORE' 
                  ? 'HARDCORE FAIL. 50% XP Penalty.' 
                  : 'Mistake made. Review your error above.'}
            </span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-green">Perfect! Streak +1 {retryCount === 0 && sessionMistakes === 0 && "(Mastery Bonus!)"}</span> :
         isFocused ? "Accuracy is paramount. One mistake restarts the quote." : ""}
      </div>
    </div>
  );
};

