                  >
                      {isArcadeLocked ? <Lock className="w-3.5 h-3.5" /> : <Gamepad2 className="w-3.5 h-3.5" />} 
                      Arcade
                  </button>

                  {/* Remediation Buttons */}
                  <div className="w-px h-6 bg-stone-200 mx-1"></div>

                  <button 
                      onClick={() => switchMode('XWORDS')}
